?php if ($isMutual): ?><span class="follow-badge">互相关注</span><?php endif; ?></div><div class="follow-bio"><?= htmlspecialchars(trim((string)($u['bio'] ?? '')) !== '' ? (string)$u['bio'] : '@' . (string)$u['username']) ?></div></div></a><?php if ($viewer && !$isSelf): ?><div class="follow-actions"><form method="post" action="/index.php" data-ajax-refresh><?= csrf_field() ?><input type="hidden" name="path" value="user/follow"><input type="hidden" name="user_id" value="<?= $uid ?>"><input type="hidden" name="action" value="<?= $isFollowing ? 'unfollow' : 'follow' ?>"><button class="soft-btn <?= $isFollowing ? 'following' : '' ?>" type="submit"><?= $isFollowing ? '已关注' : '关注' ?></button></form></div><?php endif; ?></div><?php endforeach; ?><?php else: ?><div class="empty"><?= $kw !== '' ? '没有找到相关用户' : ('暂无' . htmlspecialchars($title)) ?><?php if ($type !== 'following'): ?><br><a href="/index.php?path=section">去看看帖子，遇到喜欢的人就关注吧</a><?php endif; ?></div><?php endif; ?></section></div></main><?php require __DIR__ . '/../../layouts/theme-toggle.php'; ?><?php require __DIR__ . '/../layouts/bottom-nav.php'; ?></body></html>
